CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS lite_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('teacher','student')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lite_sessions (id_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES lite_profiles ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS lite_stores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text NOT NULL);
CREATE TABLE IF NOT EXISTS lite_games (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), teacher_id uuid NOT NULL REFERENCES lite_profiles, name text NOT NULL, code text NOT NULL UNIQUE, cycle_count int NOT NULL CHECK(cycle_count IN (3,6)), duration_seconds int NOT NULL DEFAULT 120 CHECK(duration_seconds BETWEEN 1 AND 3600), capital_min int NOT NULL CHECK(capital_min BETWEEN 10000 AND 1000000 AND capital_min%10000=0), capital_max int NOT NULL CHECK(capital_max BETWEEN capital_min AND 1000000 AND capital_max%10000=0), costs jsonb NOT NULL, enabled_events jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lite_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), game_id uuid NOT NULL REFERENCES lite_games ON DELETE CASCADE, quality text NOT NULL CHECK(quality IN ('basic','standard','premium')), unit_cost int NOT NULL CHECK(unit_cost>0), UNIQUE(game_id,quality));
CREATE TABLE IF NOT EXISTS lite_companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), game_id uuid NOT NULL REFERENCES lite_games ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES lite_profiles, name text NOT NULL, store_id uuid NOT NULL REFERENCES lite_stores, initial_capital int NOT NULL CHECK(initial_capital>0), cash int NOT NULL CHECK(cash>=0), inventory jsonb NOT NULL DEFAULT '[]', UNIQUE(game_id,student_id));
CREATE TABLE IF NOT EXISTS lite_events (id text PRIMARY KEY, category text NOT NULL, label text NOT NULL, effect jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS lite_cycles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), game_id uuid NOT NULL REFERENCES lite_games ON DELETE CASCADE, number int NOT NULL CHECK(number>0), starts_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')), seed uuid NOT NULL DEFAULT gen_random_uuid(), event_id text REFERENCES lite_events, UNIQUE(game_id,number));
CREATE UNIQUE INDEX IF NOT EXISTS lite_one_open_cycle ON lite_cycles(game_id) WHERE status='open';
CREATE TABLE IF NOT EXISTS lite_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cycle_id uuid NOT NULL REFERENCES lite_cycles ON DELETE CASCADE, company_id uuid NOT NULL REFERENCES lite_companies ON DELETE CASCADE, quality text NOT NULL CHECK(quality IN ('basic','standard','premium')), quantity int NOT NULL CHECK(quantity BETWEEN 0 AND 100000), price int NOT NULL CHECK(price BETWEEN 1 AND 100000), marketing_amount int NOT NULL CHECK(marketing_amount=0 OR marketing_amount BETWEEN 200 AND 10000), confirmed boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cycle_id,company_id));
CREATE TABLE IF NOT EXISTS lite_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cycle_id uuid NOT NULL REFERENCES lite_cycles, company_id uuid NOT NULL REFERENCES lite_companies, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cycle_id,company_id));
CREATE INDEX IF NOT EXISTS lite_company_game_idx ON lite_companies(game_id); CREATE INDEX IF NOT EXISTS lite_cycles_due_idx ON lite_cycles(ends_at) WHERE status='open'; CREATE INDEX IF NOT EXISTS lite_results_company_idx ON lite_results(company_id);
INSERT INTO lite_stores(name,description) VALUES ('Galería Central','Tienda urbana'),('Paseo del Sol','Tienda comercial'),('Plaza del Parque','Tienda de barrio'),('Mercado Azul','Tienda de mercado') ON CONFLICT(name) DO NOTHING;
